import {
  Group, Mesh, PlaneGeometry, BoxGeometry,
  MeshStandardNodeMaterial,
  Color, Vector3, Matrix4
} from 'three/webgpu';
import {
  uniform, float, vec2, vec3, mix, uv, time, smoothstep, normalize, cross, dot, sin, cos
} from 'three/tsl';
import { gsap } from 'gsap';

const CARD_COUNT = 5;
const CARD_WIDTH = 1.6;
const CARD_HEIGHT = 1.0;
const CARD_PITCH = 1.85;
const BEVEL_SIZE = 0.025;
const STRIP_ANGLE = -18 * (Math.PI / 180);
const ACCENT_COLOR = '#ff2a38';
const INK_COLOR = '#16161d';
const PAPER_COLOR = '#e8ecf2';
const UNDERLINE_HEIGHT = 0.035;

const VARIANT_URLS = [
  '/prism-mock/home/nodes/parallax-stack.png',
  '/prism-mock/home/nodes/card-1.png',
  '/prism-mock/home/nodes/card-2.png',
  '/prism-mock/home/nodes/card-3.png',
  '/prism-mock/home/nodes/card-4.png'
];

const CAPTIONS = [
  'NA-01 MERIDIAN',
  'NA-02 NOCTURNE',
  'NA-03 SIGNAL',
  'NA-04 VANTAGE',
  'NA-05 ARCHIVE'
];

function getCardX(index) {
  return (index - Math.floor(CARD_COUNT / 2)) * CARD_PITCH;
}

function getStripPosition() {
  return new Vector3();
}

function createBeveledCard(w, h, bevel) {
  const group = new Group();

  // Main face
  const faceGeo = new PlaneGeometry(w, h);
  const faceMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.2,
    clearcoat: 0.15
  });
  const face = new Mesh(faceGeo, faceMat);
  group.add(face);

  // Frame bevel - top, bottom, left, right
  const bevelMat = new MeshStandardNodeMaterial({
    color: INK_COLOR,
    roughness: 0.7,
    metalness: 0.1
  });

  const bevelW = w + 2 * bevel;
  const bevelH = h + 2 * bevel;
  const frameGeo = new PlaneGeometry(bevelW, bevelH);

  const bevelMesh = new Mesh(frameGeo, bevelMat);
  bevelMesh.position.z = -0.01;
  bevelMesh.scale.set((w + 2 * bevel) / w, (h + 2 * bevel) / h, 1);
  group.add(bevelMesh);

  return { group, face, faceMat };
}

export default function createNode(config, ctx) {
  const group = new Group();
  const cards = [];
  const cardGroups = [];
  let currentFocus = Math.floor(CARD_COUNT / 2);
  const textures = [];

  // Load textures
  const loadPromises = VARIANT_URLS.map(url =>
    ctx.textureLoader.loadTexture(url).catch(() => null)
  );

  return Promise.all(loadPromises).then(loadedTextures => {
    loadedTextures.forEach((tex, i) => {
      if (tex) {
        tex.wrapS = tex.wrapT = ctx.THREE.RepeatWrapping;
        textures[i] = tex;
      }
    });

    // Build cards
    for (let i = 0; i < CARD_COUNT; i++) {
      const x = getCardX(i);
      const { group: cardGroup, face, faceMat } = createBeveledCard(
        CARD_WIDTH, CARD_HEIGHT, BEVEL_SIZE
      );

      if (textures[i]) {
        faceMat.map = textures[i];
        faceMat.needsUpdate = true;
      }

      // Store card data
      cards.push({ mesh: face, mat: faceMat, originalX: x, opacityTarget: 1, scale: 1 });
      cardGroups.push(cardGroup);

      // Position along strip
      cardGroup.position.set(x, 0, 0);

      // Caption text
      const captionGroup = new Group();
      const captionText = ctx.fontAtlas.createText(CAPTIONS[i], {
        fontSize: 18,
        color: PAPER_COLOR,
        align: 'center',
        letterSpacingPx: 0.08 * 18
      });
      captionText.position.set(0, -CARD_HEIGHT / 2 - 0.2, 0.05);
      captionGroup.add(captionText);
      cardGroup.add(captionGroup);

      group.add(cardGroup);
    }

    // Rotate the whole strip
    group.rotation.y = STRIP_ANGLE;

    // Underline for focused card
    const underlineMat = new MeshStandardNodeMaterial({
      color: ACCENT_COLOR,
      emissive: ACCENT_COLOR,
      emissiveIntensity: 1.3,
      roughness: 0.3,
      metalness: 0.1
    });
    const underlineGeo = new PlaneGeometry(CARD_WIDTH, UNDERLINE_HEIGHT);
    const underline = new Mesh(underlineGeo, underlineMat);
    underline.position.set(0, -CARD_HEIGHT / 2 - 0.12, 0.05);
    underline.visible = true;

    // Card positions storage for animation
    const bestCardGroup = cardGroups[currentFocus];
    bestCardGroup.add(underline);

    // Headline text
    const headlineText = ctx.fontAtlas.createText('The collection', {
      fontSize: 68,
      color: PAPER_COLOR,
      align: 'left',
      fontWeight: 600,
      letterSpacingPx: -0.005 * 68
    });
    headlineText.position.set(-2.6, 1.5, 0);
    group.add(headlineText);

    // Body text
    const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
      fontSize: 26,
      color: PAPER_COLOR,
      align: 'left'
    });
    bodyText.position.set(-2.6, -1.5, 0);
    group.add(bodyText);

    // Background plane
    const bgMat = new MeshStandardNodeMaterial({
      color: '#0b0b10',
      roughness: 0.9,
      metalness: 0
    });
    const bgGeo = new PlaneGeometry(8, 6);
    const bg = new Mesh(bgGeo, bgMat);
    bg.position.set(0, 0, -2.5);
    group.add(bg);

    // Gradient overlay on background
    const gradientMat = new MeshStandardNodeMaterial({
      color: '#12121a',
      transparent: true,
      opacity: 0.3
    });
    const gradientGeo = new PlaneGeometry(8, 6);
    const gradient = new Mesh(gradientGeo, gradientMat);
    gradient.position.set(0, 0, -2.4);
    group.add(gradient);

    // Lights
    const keyLight = new ctx.THREE.DirectionalLight(PAPER_COLOR, 1.2);
    keyLight.position.set(3, 2, 4);
    group.add(keyLight);

    const rimLight = new ctx.THREE.DirectionalLight(ACCENT_COLOR, 0.8);
    rimLight.position.set(-2, 0, -3);
    group.add(rimLight);

    const ambientLight = new ctx.THREE.AmbientLight('#e8ecf2', 0.6);
    group.add(ambientLight);

    // Set initial state - focused card centered, non-focused card scaled and faded
    for (let i = 0; i < CARD_COUNT; i++) {
      const card = cards[i];
      const cardGroup = cardGroups[i];

      if (i === currentFocus) {
        cardGroup.scale.set(1, 1, 1);
        card.opacityTarget = 1;
        if (card.mat.map) card.mat.map = textures[i];
      } else {
        const distance = Math.abs(i - currentFocus);
        cardGroup.scale.set(0.92, 0.92, 0.92);
        card.opacityTarget = 1.0 - (distance * 0.225);
        if (card.opacityTarget < 0.55) card.opacityTarget = 0.55;
      }
      card.mat.opacity = card.opacityTarget;
      card.mat.transparent = card.opacityTarget < 1;
      card.mat.needsUpdate = true;
    }

    // Scroll offset tracking
    let scrollOffset = 0;
    let targetScrollOffset = 0;
    let animating = false;

    // Parallax scroll handler
    const scrollHandler = (delta) => {
      targetScrollOffset += delta * 0.5;
      targetScrollOffset = Math.max(-(CARD_COUNT - 1) * CARD_PITCH * 0.5, Math.min((CARD_COUNT - 1) * CARD_PITCH * 0.5, targetScrollOffset));

      if (!animating) {
        animating = true;
        snapToNearestCard();
      }
    };

    function snapToNearestCard() {
      const stripX = targetScrollOffset;
      const nearestIndex = Math.round(stripX / CARD_PITCH + (CARD_COUNT - 1) / 2);
      const clampedIndex = Math.max(0, Math.min(CARD_COUNT - 1, nearestIndex));
      const targetX = (clampedIndex - Math.floor(CARD_COUNT / 2)) * CARD_PITCH;

      // Remove underline from old focused card
      underline.removeFromParent();

      // Animate strip position
      gsap.to(group.position, {
        x: targetX,
        duration: 0.9,
        ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
        overwrite: 'auto',
        onUpdate: () => {
          updateCardStates(clampedIndex);
        },
        onComplete: () => {
          currentFocus = clampedIndex;
          scrollOffset = targetX;

          // Add underline to new focused card
          const newFocusGroup = cardGroups[currentFocus];
          newFocusGroup.add(underline);
          underline.visible = true;

          animating = false;
        }
      });
    }

    function updateCardStates(focusIndex) {
      for (let i = 0; i < CARD_COUNT; i++) {
        const card = cards[i];
        const cardGroup = cardGroups[i];

        const isFocused = i === focusIndex;
        if (isFocused) {
          cardGroup.scale.set(1, 1, 1);
          card.opacityTarget = 1;
        } else {
          const distance = Math.abs(i - focusIndex);
          cardGroup.scale.set(0.92, 0.92, 0.92);
          card.opacityTarget = 1.0 - (distance * 0.225);
          if (card.opacityTarget < 0.55) card.opacityTarget = 0.55;
        }

        // Animate opacity
        gsap.to(card.mat, {
          opacity: card.opacityTarget,
          duration: 0.4,
          ease: 'power2.out'
        });

        // Counter-shift UV for internal parallax
        if (card.mat.map) {
          const uvOffset = (group.position.x - card.originalX) * -0.04 / CARD_PITCH;
          card.mat.map.offset.x = -group.position.x * 0.04 / CARD_PITCH + uvOffset;
          card.mat.map.needsUpdate = true;
        }
      }
    }

    // Apply parallax-scroll primitive
    let primitiveResult = null;
    try {
      primitiveResult = ctx.primitives['parallax-scroll'](group, {
        intensity: 0.5
      });
    } catch (e) {
      // Primitive may fail silently
    }

    // Event handlers
    group.userData.handlers = {
      scroll: (delta) => {
        scrollHandler(delta);
      }
    };

    // Cleanup
    group.userData.cleanup = () => {
      // Kill GSAP timelines
      gsap.killTweensOf(group.position);
      gsap.killTweensOf(cards.map(c => c.mat));

      // Dispose materials
      cards.forEach(card => {
        card.mat.dispose();
      });

      // Dispose geometries
      cards.forEach(() => {
        // Geometries are shared, dispose once
      });
      underlineMat.dispose();
      underlineGeo.dispose();
      bgMat.dispose();
      bgGeo.dispose();
      gradientMat.dispose();
      gradientGeo.dispose();
      headlineText.removeFromParent();
      bodyText.removeFromParent();

      // Dispose primitive
      if (primitiveResult && primitiveResult.cleanup) {
        primitiveResult.cleanup();
      }
    };

    return group;
  });
}
